assert len(Q) == 52, len(Q)
HEAD = ["taskCode", "approach", "difficulty", "type", "stem", "optionA", "optionB", "optionC", "optionD", "correct",
        "rationaleA", "rationaleB", "rationaleC", "rationaleD", "whyCorrect", "mindset", "keyConcept", "language", "aiAssisted"]
wb = Workbook()
ws = wb.active
ws.title = "Questions"
ws.append(HEAD)
for task, approach, diff, qtype, stem, opts, why, mindset, concept in Q:
    assert len(opts) == 4 and len(stem) >= 20
    correct = ";".join("ABCD"[i] for i, o in enumerate(opts) if o[1])
    assert (qtype == "single") == (len(correct) == 1)
    ws.append([task, approach, diff, qtype, stem, *[o[0] for o in opts], correct, *[o[2] for o in opts], why, mindset, concept, "en", "TRUE"])
for c in ws[1]:
    c.font = Font(bold=True, color="FFFFFF")
    c.fill = PatternFill("solid", fgColor="1B4A78")
for col, width in zip("ABCDEFGHIJKLMNOPQRS", [11, 11, 10, 9, 70, 40, 40, 40, 40, 8, 40, 40, 40, 40, 60, 35, 22, 8, 10]):
    ws.column_dimensions[col].width = width
for row in ws.iter_rows(min_row=2):
    for c in row:
        c.alignment = Alignment(wrap_text=True, vertical="top")
ws.freeze_panes = "B2"
notes = wb.create_sheet("Read me")
for line in [
    "Starter drafts: 52 original questions, two per task of the July 2026 outline.",
    "Drafted with AI help (aiAssisted = TRUE). They are not exam content yet.",
    "Import them in the admin panel (Import → choose this file → Check rows → Import). Only the first sheet is read.",
    "Each becomes a draft and must pass expert review and language review, then be published by an administrator.",
    "Reviewers: check every answer and rationale against current PMI references and your own expertise; rewrite freely.",
    "Mix: " + ", ".join(f"{n} {k}" for k, n in __import__("collections").Counter(q[1] for q in Q).items())
    + "; " + str(sum(q[3] == "multiple" for q in Q)) + " multiple-response; easy, medium and hard.",
]:
    notes.append([line])
notes.column_dimensions["A"].width = 110
from collections import Counter
print(Counter(q[1] for q in Q), Counter(q[3] for q in Q), Counter(q[2] for q in Q))
wb.save(__file__.replace("starter_drafts.py", "starter-drafts.xlsx"))
print("written content/starter-drafts.xlsx")
